toad_implementation.code_blueprint:
canvas {
  size: 800px 600px;
  fill: #111827;
  font-family: "Roboto, sans-serif";
}

>charcoal = #111827;
>indigo = #6366F1;
>cyan = #06B6D4;
>amber = #F59E0B;
>barBackdrop = #1F2937;
>textDim = #9CA3AF;
>textWhite = #F9FAFB;

text #chartTitle {
  at: top left of canvas offset 40px 40px;
  content: "REVENUE DISTRIBUTION BY REGION (Q3)";
  font-size: 16px;
  font-weight: 700;
  color: >textWhite;
}

rect #row1Track {
  at: below #chartTitle offset 40px;
  size: 560px 24px;
  fill: >barBackdrop;
  radius: 4px;
}

rect #row1Fill {
  at: top left of #row1Track;
  size: 420px 24px;
  fill: >indigo;
  radius: 4px;
}

text #row1Label {
  at: right of #row1Track offset 16px;
  content: "EMEA (75%)";
  font-size: 12px;
  font-weight: 700;
  color: >textWhite;
}

rect #row2Track {
  at: below #row1Track offset 24px;
  size: 560px 24px;
  fill: >barBackdrop;
  radius: 4px;
}

rect #row2Fill {
  at: top left of #row2Track;
  size: 280px 24px;
  fill: >cyan;
  radius: 4px;
}

text #row2Label {
  at: right of #row2Track offset 16px;
  content: "AMER (50%)";
  font-size: 12px;
  font-weight: 700;
  color: >textWhite;
}

rect #row3Track {
  at: below #row2Track offset 24px;
  size: 560px 24px;
  fill: >barBackdrop;
  radius: 4px;
}

rect #row3Fill {
  at: top left of #row3Track;
  size: 140px 24px;
  fill: >amber;
  radius: 4px;
}

text #row3Label {
  at: right of #row3Track offset 16px;
  content: "APAC (25%)";
  font-size: 12px;
  font-weight: 700;
  color: >textWhite;
}
